// Function node to convert registers to floating-point values
function registersToFloat(registers) {
    var buffer = new ArrayBuffer(4);
    var view = new DataView(buffer);
    view.setUint16(0, registers[0], false); // false for big-endian
    view.setUint16(2, registers[1], false); // false for big-endian
    return view.getFloat32(0, false);
}

// Declare data variable once
var data;

if (Array.isArray(msg.payload)) {
    data = msg.payload;
} else if (msg.payload && msg.payload.data && Array.isArray(msg.payload.data)) {
    data = msg.payload.data;
} else {
    node.error("Payload is not an array or does not contain an array");
    return null;
}

// Ensure there are enough registers
if (data.length >= 12) {
    msg.payload = {
        voltage1: registersToFloat(data.slice(0, 2)),
        voltage2: registersToFloat(data.slice(2, 4)),
        voltage3: registersToFloat(data.slice(4, 6)),
        current1: registersToFloat(data.slice(6, 8)),
        current2: registersToFloat(data.slice(8, 10)),
        current3: registersToFloat(data.slice(10, 12))
    };
} else {
    node.error("Insufficient register data");
    return null; // Stop further processing
}

return msg;

